contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum, set LogFile to some existing LogFile (use address(0) allowed), initialize, put funds, then attempt Collect.
    // Inputs:
    // putAmt - amount of wei to deposit via Put (and fallback), must be available on this contract
    // lock - lockTime parameter to Put
    // collectAmt - amount to attempt Collect
    // minSum - value to set MinSum before putting
    // logAddr - address to set as LogFile (can be 0)
    function run(uint putAmt, uint lock, uint collectAmt, uint minSum, address logAddr) public payable {
        require(address(this).balance >= putAmt, "insufficient test balance");

        // Configure contract c before enabling initialized flag
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Record balances and holder before Put
        uint before_c_balance = address(c).balance;
        (uint unlockBefore, uint balBefore) = getHolder(address(this));

        // Do a Put of putAmt
        c.Put{value: putAmt}(lock);

        // Record after put
        (uint unlockAfterPut, uint balAfterPut) = getHolder(address(this));
        uint after_c_balance = address(c).balance;

        // Try to Collect collectAmt, capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-collect state
        (uint unlockAfter, uint balAfter) = getHolder(address(this));
        uint final_c_balance = address(c).balance;

        // General property to assert:
        // If Collect did not revert then:
        //  - the holder balance decreased by collectAmt
        //  - the contract's balance decreased by collectAmt
        // Otherwise (if reverted) balances remain unchanged from after the Put
        // Also ensure after Put the recorded balance increased by putAmt and contract balance increased by putAmt
        assert(
            // Put effect: contract and holder increased by putAmt
            (balAfterPut == balBefore + putAmt && after_c_balance == before_c_balance + putAmt)
            && (
                // If Collect succeeded, balances decreased by collectAmt
                (!reverted && balAfter + collectAmt == balAfterPut && final_c_balance + collectAmt == after_c_balance)
                // If Collect reverted, balances unchanged
                || (reverted && balAfter == balAfterPut && final_c_balance == after_c_balance)
            )
        );
    }

    // helper to read the public struct Acc via its auto-generated getter: Acc(address) returns (uint unlockTime, uint balance)
    function getHolder(address who) internal view returns (uint,uint) {
        // The auto-generated getter for mapping (address => Holder) public Acc;
        // Solidity will generate function Acc(address) returning (uint unlockTime, uint balance)
        (uint u, uint b) = c.Acc(who);
        return (u,b);
    }

    // allow receiving ETH for test funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test interplay of Put and Collect for the test-deployer account (this contract).
    // Parameters:
    // putAmt - amount of wei to deposit via Put (must be funded to this contract)
    // lock - lockTime parameter to Put
    // collectAmt - amount to attempt Collect
    // minSum - value to set MinSum before putting
    // logAddr - address to set as LogFile
    function run(uint putAmt, uint lock, uint collectAmt, uint minSum, address logAddr) public payable {
        require(address(this).balance >= putAmt, "insufficient test balance");

        // Configure c (calls that change c state must be top-level statements)
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Observe before-state
        uint before_c_balance = address(c).balance;
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));

        // Do Put (state-changing, top-level)
        c.Put{value: putAmt}(lock);

        // Observe after Put
        uint after_c_balance = address(c).balance;
        (uint unlockAfterPut, uint balAfterPut) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe final state
        uint final_c_balance = address(c).balance;
        (uint unlockFinal, uint balFinal) = c.Acc(address(this));

        // General rule (single assert):
        // 1) The Put increased both the holder balance and contract balance exactly by putAmt.
        // 2) After attempting Collect, either it reverted and balances remain as after Put,
        //    or it succeeded and both the holder balance and contract balance decreased by collectAmt.
        assert(
            // Put effect must hold
            balAfterPut == balBefore + putAmt
            && after_c_balance == before_c_balance + putAmt
            && (
                // If Collect reverted -> balances unchanged
                (collectReverted && balFinal == balAfterPut && final_c_balance == after_c_balance)
                // If Collect succeeded -> both balances decreased by collectAmt
                || (!collectReverted && balAfterPut >= collectAmt && balFinal + collectAmt == balAfterPut && final_c_balance + collectAmt == after_c_balance)
            )
        );
    }

    // allow receiving ETH for test funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a successful Put with positive value increases both the contract's stored holder balance
    // for this contract and the on-chain balance of c by exactly the sent amount.
    // Parameters:
    // amount - wei to send to c.Put
    // lock - lockTime parameter to Put
    // minSum - value to set MinSum before calling Initialized (arbitrary)
    // logAddr - address to set as LogFile (arbitrary)
    function run(uint amount, uint lock, uint minSum, address logAddr) public payable {
        // need funds to send amount
        require(address(this).balance >= amount, "funds");
        // Setup c so that Put won't revert due to initialization gates
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Read before values via public getters
        uint beforeContractBalance = address(c).balance;
        (, uint holderBefore) = c.Acc(address(this));

        // We only assert behavior for positive sends; if amount == 0, Put will still execute but does not change balances
        // so require amount > 0 to make the rule meaningful
        require(amount > 0, "amount>0");

        // Perform Put sending Ether; top-level state-changing call
        c.Put{value: amount}(lock);

        // Read after values
        uint afterContractBalance = address(c).balance;
        (, uint holderAfter) = c.Acc(address(this));

        // General rule: both the on-chain balance of c and the stored holder balance for this address
        // increase by exactly amount after Put
        assert(afterContractBalance == beforeContractBalance + amount && holderAfter == holderBefore + amount);
    }

    // Allow this test contract to receive ETH for funding the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If Collect succeeds (does not revert) for caller == this contract and amount `am`,
    // then c.Acc(this).balance is no greater than before, and address(c).balance decreased by exactly am.
    function run(uint am, uint lock, uint minSum, address logAddr) public payable {
        require(address(this).balance >= am, "funds");

        // setup: initialize c so Put/Collect won't be blocked by initialization gates
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // seed the account via Put so there is some balance to collect from
        // ensure we send at least am so Collect may succeed
        uint seed = am;
        // if seed==0, make it 1 to ensure Put does something; but keep relation seed >= am
        if (seed == 0) { seed = 1; }
        require(address(this).balance >= seed, "funds2");

        // record balances before Put
        uint beforeContractBal = address(c).balance;
        (, uint holderBefore) = c.Acc(address(this));

        // perform Put with some lock (could be zero)
        c.Put{value: seed}(lock);

        // now attempt Collect and observe whether it reverts
        bool reverted;
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        reverted = !success;

        // read after-values
        uint afterContractBal = address(c).balance;
        (, uint holderAfter) = c.Acc(address(this));

        // If Collect did not revert then the contract's balance must have decreased by am
        // and the holder's stored balance must be <= its previous value (it may have decreased by am).
        assert(reverted || (afterContractBal + am == beforeContractBal + seed && holderAfter <= holderBefore + seed));
    }

    receive() external payable {}
}

