        require(address(this).balance >= seed, "insufficient test funds");

        // initialize c so Put/Collect won't be blocked by initialization gates
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // read before-values (view calls)
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // perform Put to fund the holder (state-changing call must be top-level)
        c.Put{value: seed}(lock);

        // record intermediate balances after Put
        uint midContractBal = address(c).balance;
        (uint midUnlock, uint midHolderBal) = c.Acc(address(this));

        // attempt Collect using direct call on c; capture whether it reverted
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));

