contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to pass amounts and lock time. We will: put some funds via Put, optionally set MinSum and Initialized/Log
    // Then attempt Collect and assert the general invariant described.
    function run(uint putAmount, uint lockTime, uint collectAmount, uint minSum, address logAddr) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Ensure contract has a LogFile and MinSum set before initializing and using Put/Collect.
        // Set MinSum and LogFile only if not initialized. These calls may revert if already initialized in c,
        // but per problem the checker deploys fresh c so these will succeed.
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Record holder info before interactions using public getter Acc(address)
        // Acc is a public mapping to Holder with (unlockTime, balance) in that order
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Put funds into c from this contract
        c.Put{value: putAmount}(lockTime);

        // Read state after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalBeforeCollect = address(c).balance;

        // Now attempt Collect(amount). It may revert; capture that.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after Collect (if call reverted, state should be unchanged)
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General rule asserted:
        // If the collector met the on-chain preconditions at the moment of call (midBalance >= minSum && midBalance >= collectAmount && block.timestamp > midUnlock)
        // then Collect must either succeed and reduce the on-chain recorded balance by collectAmount and reduce c's Ether balance by collectAmount,
        // or it may revert. If preconditions were not met, Collect must revert or leave balances unchanged (we express the rule only for the former case by implication).
        bool preconds = (midBalance >= minSum) && (midBalance >= collectAmount) && (block.timestamp > midUnlock);

        // When Collect succeeded (not reverted) and preconds held, then afterBalance == midBalance - collectAmount and cBalAfter == cBalBeforeCollect - collectAmount.
        // If reverted or preconds didn't hold, then it's allowed that balances didn't decrease.
        bool success_effects = (!reverted) ? (afterBalance + collectAmount == midBalance && cBalAfter + collectAmount == cBalBeforeCollect) : true;

        assert(!preconds || success_effects);
    }

    receive() external payable {}
}

