contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to Put some funds and then Collect them.
    // Params:
    // amountPut: amount of wei to send to Put (must be <= this contract balance when calling run)
    // lockTime: lock extension passed to Put
    // collectAmount: amount to attempt to Collect
    function run(uint amountPut, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= amountPut, "insufficient test balance");

        // ensure Log and MinSum can be set before initialization
        // set a dummy LogFile (address(0) is allowed but must be convertible) - skip setting to avoid reverts
        // Call Put to deposit funds into c for msg.sender == this contract
        c.Put{value: amountPut}(lockTime);

        // read balance before Collect via the public getter Acc
        (uint beforeUnlockTime, uint beforeBalance) = getAcc(address(this));
        uint beforeCbalance = address(c).balance;

        // Attempt Collect and capture whether it reverted and whether the external call succeeded.
        bool reverted = false;
        bool callSucceeded = false;
        // We need to detect whether the internal call to msg.sender.call returned true.
        // The Collect function will only attempt the external call if conditions hold; if it does and it succeeds,
        // we expect the stored balance to decrease by collectAmount and contract balance to decrease by collectAmount.
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
            // After successful Collect (or Collect returning without revert), read state
            (uint afterUnlockTime, uint afterBalance) = getAcc(address(this));
            uint afterCbalance = address(c).balance;
            // If contract's balance decreased exactly by collectAmount and stored balance decreased by collectAmount,
            // then conclude the external transfer must have succeeded. We record that.
            if (beforeBalance >= collectAmount && afterBalance == beforeBalance - collectAmount && beforeCbalance >= collectAmount && afterCbalance == beforeCbalance - collectAmount) {
                callSucceeded = true;
            } else {
                callSucceeded = false;
            }
        } catch {
            reverted = true;
            // when reverted, read state anyway
            (uint afterUnlockTime, uint afterBalance) = getAcc(address(this));
            uint afterCbalance = address(c).balance;
            callSucceeded = false;
        }

        // General property: If Collect did perform and succeed in transferring collectAmount out (as observed
        // by both storage and contract balance decreasing by collectAmount), then the stored balance decreased by that amount
        // and the contract's ETH balance decreased by that amount. We express this as a single assert: if observed decreases
        // match collectAmount then they must be consistent with each other.

        // Re-read to obtain final observable values for a single assert expression
        (uint finalUnlockTime, uint finalBalance) = getAcc(address(this));
        uint finalCbalance = address(c).balance;

        // The assert encodes the invariant: if finalBalance == beforeBalance - collectAmount and finalCbalance == beforeCbalance - collectAmount
        // then both decreases must hold simultaneously (this is tautological given how we wrote it), but importantly it ties storage decrease to contract balance decrease,
        // ensuring Collect's transfer actually reduces both storage and contract ETH together.
        assert( !((beforeBalance >= collectAmount && finalBalance == beforeBalance - collectAmount && beforeCbalance >= collectAmount) && !(finalCbalance == beforeCbalance - collectAmount)) );
    }

    // helper to call the public mapping getter Acc (auto-generated returns Holder struct components)
    function getAcc(address a) internal returns (uint unlockTime, uint balance) {
        // The compiler generates a getter with signature Acc(address) returns (uint,uint)
        (unlockTime, balance) = c.Acc(a);
    }

    // receive to accept ETH from C when Collect pays out
    receive() external payable {}
}

