        // ensure this test contract can send the putAmount
        require(address(this).balance >= putAmount);

        // Initialize configuration on c (must be done before Put/Collect to avoid reverts due to uninitialized state)
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

