        (, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Perform Put to fund msg.sender (this contract) on c; allow Put to revert
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read intermediate state after Put (whether reverted or not)
        (, uint midHolderBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Now attempt Collect with collectAmount; record if it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

