        // - If Collect succeeded then contract balance decreased by exactly the amount withdrawn
        //   and the holder's recorded balance decreased by the same amount.
        // - If Collect reverted then both contract and holder balances are unchanged by the Collect call
        //   (they may have changed from the Put call). We express this by comparing mid -> after deltas.
        // Avoid arithmetic underflow in test by using comparisons in two cases.

        bool successCase = (!collectReverted)
            && (midContractBalance >= afterContractBalance)
            && (midHolderBalance >= afterHolderBalance)
            && (midContractBalance - afterContractBalance == midHolderBalance - afterHolderBalance)
            // additionally, ensure the contract balance did not increase on successful Collect
            && (afterContractBalance <= midContractBalance);

        bool revertCase = collectReverted
