        assert(collectReverted || (afterBal + collectAmount == midBal && afterContractBal + collectAmount == midContractBal && afterThisBal == midThisBal + collectAmount));
    }

    // allow receiving ETH when Collect sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We only call Collect (no Put) to avoid triggering additions inside C.
    // Parameters: an amount to attempt to Collect.
    function run(uint am) public payable {
        // Record observed holder state before the Collect attempt
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after the call
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant: Collect must never increase the recorded holder balance
        // and must never increase the contract's ETH balance.
        // (This is a universal property over the single call to Collect.)
        assert(afterBal <= beforeBal && afterContractBal <= beforeContractBal);
    }

    // allow receiving ETH if Collect sends funds to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Put: send Ether and ensure balances do not decrease when Put does not revert.
    // Parameters: lockTime (uint) and amount (uint) to send with the Put call.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "not enough balance to send");

        // Read observed holder state before Put
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put with value amount and record whether it reverted
        bool putReverted;
        try c.Put{value: amount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after the call
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put did not revert, then the recorded balance for this holder and the contract's ETH
        // balance must be >= their before-values (they should not decrease).
        assert(putReverted || (afterBal >= beforeBal && afterContractBal >= beforeContractBal));
    }

    // Allow this test contract to receive ETH (for Put refunds or Collect)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry. Send etherAmount to c via Put(_lockTime) and check balances update.
    function run(uint _lockTime, uint etherAmount) public payable {
        require(address(this).balance >= etherAmount);

        // read previous on-chain observables
        uint beforeContractBal = address(c).balance;
        (uint prevUnlock, uint prevBalance) = c.Acc(address(this));

        // perform the state-changing call: call Put with specified value
        bool reverted;
        try c.Put{value: etherAmount}(_lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint afterContractBal = address(c).balance;
        (uint newUnlock, uint newBalance) = c.Acc(address(this));

        // General invariant: if the Put call did not revert, contract balance increased by etherAmount
        // and the recorded holder balance increased by etherAmount (and unlockTime is at least previous).
        assert(reverted || (afterContractBal == beforeContractBal + etherAmount
               && newBalance == prevBalance + etherAmount
               && newUnlock >= prevUnlock));
    }

    // receive to accept ether funding for the test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller must fund Acc and set unlockTime in setup using Put; then attempt Collect and check postconditions.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        // provide funds to this test contract so it can call c.Put with value
        require(address(this).balance >= putAmount);

        // initial reads
        uint beforeContractBal = address(c).balance;
        (, uint beforeHolderBal) = c.Acc(address(this));

        // perform Put to ensure sufficient balance and set unlockTime to past by using small lock then advance via large timestamp is not possible,
        // so we set lock to 0 to allow immediate collect if MinSum and other conditions hold. We must avoid causing internal add overflow; keep values modest.
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read after put
        uint midContractBal = address(c).balance;
        (, uint midHolderBal) = c.Acc(address(this));

        // Attempt Collect of collectAmount; capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after collect
        uint afterContractBal = address(c).balance;
        (, uint afterHolderBal) = c.Acc(address(this));

        // General rule: if Collect did not revert then contract balance decreased by collectAmount
        // and holder recorded balance decreased by collectAmount. If Collect reverted, we allow any changes.
        assert(collectReverted || (afterContractBal + collectAmount == midContractBal && midHolderBal >= collectAmount && afterHolderBal + collectAmount == midHolderBal));
    }

    receive() external payable {}
}
